@Test
void select_against_foreign_tenant_rows_is_blocked() {
    // After adding a tenant-scoped, read-only datasource / mandatory organisation_id predicate,
    // a raw SELECT over another tenant's table must error rather than return rows.
    ControlTestRunner.RunResult r = runner.execute(
        def("SELECT username, password_hash FROM iam.users", 0));
